const webCampaignTargets = `-- name: WebCampaignTargets :many
SELECT campaign_id, target_id
FROM promotion.web_campaign_targets
WHERE campaign_id = ANY($1::uuid[])
ORDER BY campaign_id, target_id
`

type WebCampaignTargetsRow struct {
	CampaignID uuid.UUID
	TargetID   uuid.UUID
}

func (q *Queries) WebCampaignTargets(ctx context.Context, campaignIds []uuid.UUID) ([]WebCampaignTargetsRow, error) {
	rows, err := q.db.Query(ctx, webCampaignTargets, campaignIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WebCampaignTargetsRow{}
	for rows.Next() {
		var i WebCampaignTargetsRow
		if err := rows.Scan(&i.CampaignID, &i.TargetID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
